package com.taryo.appalarm;
import android.Manifest; import android.app.AlertDialog; import android.content.pm.PackageManager; import android.database.Cursor; import android.os.Bundle; import android.provider.CalendarContract; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; import androidx.core.app.ActivityCompat; import androidx.core.content.ContextCompat; import java.util.ArrayList; import java.util.Calendar; import java.util.List;
/** Imports an upcoming calendar event as a one-time local reminder. */
public class CalendarActivity extends AppCompatActivity {
 private static final int REQ=730; private final List<Long> starts=new ArrayList<>(); private final List<String> titles=new ArrayList<>();
 @Override protected void onCreate(Bundle b){super.onCreate(b); if(ContextCompat.checkSelfPermission(this,Manifest.permission.READ_CALENDAR)!=PackageManager.PERMISSION_GRANTED) ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.READ_CALENDAR},REQ); else loadEvents();}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g); if(r==REQ&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)loadEvents();else{Toast.makeText(this,"カレンダーの読み取りが許可されていません",Toast.LENGTH_LONG).show();finish();}}
 private void loadEvents(){Cursor c=null;try{long begin=System.currentTimeMillis(),end=begin+90L*24*60*60*1000;android.net.Uri uri=CalendarContract.Instances.CONTENT_URI.buildUpon().appendPath(Long.toString(begin)).appendPath(Long.toString(end)).build();c=getContentResolver().query(uri,new String[]{CalendarContract.Instances.TITLE,CalendarContract.Instances.BEGIN},null,null,CalendarContract.Instances.BEGIN+" ASC");if(c!=null)while(c.moveToNext()&&starts.size()<80){long t=c.getLong(1);if(t>=begin){titles.add(c.getString(0)==null?"予定":c.getString(0));starts.add(t);}}}catch(SecurityException e){Toast.makeText(this,"カレンダーを読み取れません",Toast.LENGTH_LONG).show();finish();return;}finally{if(c!=null)c.close();} if(titles.isEmpty()){Toast.makeText(this,"今後90日以内の予定が見つかりません",Toast.LENGTH_LONG).show();finish();return;}new AlertDialog.Builder(this).setTitle("リマインダーにする予定を選択").setItems(titles.toArray(new String[0]),(d,i)->add(i)).setOnCancelListener(d->finish()).show();}
 private void add(int i){Calendar c=Calendar.getInstance();c.setTimeInMillis(starts.get(i));AlarmEntry e=new AlarmEntry();e.id=(int)(System.currentTimeMillis()&0x7fffffff);e.hour=c.get(Calendar.HOUR_OF_DAY);e.minute=c.get(Calendar.MINUTE);e.year=c.get(Calendar.YEAR);e.month=c.get(Calendar.MONTH)+1;e.day=c.get(Calendar.DAY_OF_MONTH);e.mode=AlarmEntry.MODE_DATE;e.label=titles.get(i);e.calendarEnabled=true;android.content.SharedPreferences p=getSharedPreferences("appalarm_prefs",MODE_PRIVATE);List<AlarmEntry> all=AlarmEntry.loadAll(p);all.add(e);AlarmEntry.saveAll(p,all);AlarmReceiver.rescheduleAll(this,all);Toast.makeText(this,"予定をリマインダーに追加しました",Toast.LENGTH_LONG).show();finish();}
}
